import {startBenchmark,downloadBenchmark} from './performance-tools.js';
import {preferences,updatePreferences,canonicalKeys,reducedMotion} from './preferences.js';
const streets=document.body.dataset.game==='streets'||/\/streets(?:\.html)?$/.test(location.pathname);
const style=document.createElement('link');style.rel='stylesheet';style.href='settings.css';document.head.append(style);
function apply(){document.documentElement.classList.toggle('high-contrast',preferences.contrast);document.documentElement.classList.toggle('large-text',preferences.largeText);document.documentElement.classList.toggle('reduce-motion',reducedMotion());document.documentElement.classList.toggle('hide-hints',!preferences.showHints);document.documentElement.style.setProperty('--touch-scale',preferences.touchScale);}
apply();window.addEventListener('brasa:settings',apply);matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',apply);
const launch=document.createElement('button');launch.className='settings-launch';launch.textContent='CONFIGURAÇÕES & ACESSIBILIDADE';(document.querySelector('.audio-panel')||document.querySelector('.game-shell')).after(launch);
const modal=document.createElement('dialog');modal.className='settings-dialog';modal.setAttribute('aria-label','Configurações e acessibilidade');document.body.append(modal);let binding=null;
const labels={KeyW:streets?'1P · Fundo':'1P · Pular',KeyA:'1P · Esquerda',KeyS:streets?'1P · Frente':'1P · Defesa',KeyD:'1P · Direita',Space:'1P · Pular',ShiftLeft:'1P · Defesa',KeyF:'1P · Soco',KeyG:'1P · Chute',KeyH:'1P · Especial',KeyR:'1P · Super',KeyT:'1P · Finalizar',ArrowUp:streets?'2P · Fundo':'2P · Pular',ArrowLeft:'2P · Esquerda',ArrowDown:streets?'2P · Frente':'2P · Defesa',ArrowRight:'2P · Direita',KeyO:'2P · Pular',KeyP:'2P · Defesa',KeyJ:'2P · Soco',KeyK:'2P · Chute',KeyL:'2P · Especial',KeyU:'2P · Super',KeyI:'2P · Finalizar'};
const keyName=k=>k.replace('Key','').replace('Arrow','Seta ').replace('ShiftLeft','Shift').replace('Space','Espaço');
function paint(){modal.innerHTML=`<h2>JOGUE DO SEU JEITO</h2><p>Preferências ficam neste aparelho. A dificuldade vale para uma nova partida. Salas online usam a dificuldade escolhida pelo criador.</p><div class="settings-grid"><label>DIFICULDADE<select data-setting="difficulty"><option value="story">História · mais acessível</option><option value="standard">Padrão</option><option value="arcade">Arcade · mais desafio</option></select></label><label>MOVIMENTO<select data-setting="motion"><option value="system">Seguir o aparelho</option><option value="reduced">Reduzir animações e tremor</option><option value="full">Completo</option></select></label><label>QUALIDADE VISUAL<select data-setting="quality"><option value="auto">Automática</option><option value="low">Econômica</option><option value="high">Alta</option></select></label><label>BOTÕES DE TOQUE<select data-setting="touchScale"><option value="1">Padrão</option><option value="1.2">Grandes</option><option value="1.4">Muito grandes</option></select></label><label class="check"><input type="checkbox" data-setting="contrast">Alto contraste</label><label class="check"><input type="checkbox" data-setting="largeText">Texto ampliado</label><label class="check"><input type="checkbox" data-setting="showHints">Mostrar dicas</label></div><h3>TECLADO · 1P E 2P</h3><p>Escolha um comando e pressione uma tecla. ESC cancela. Teclas repetidas trocam de comando para evitar conflitos.</p><div class="bindings">${canonicalKeys.filter(k=>streets||!['Space','ShiftLeft','KeyO','KeyP'].includes(k)).map(k=>`<div class="binding"><span>${labels[k]}</span><button aria-label="Alterar ${labels[k]}" data-bind="${k}">${keyName(preferences.bindings[k]||k)}</button></div>`).join('')}</div><p role="status" id="binding-status" aria-live="polite"></p><h3>DESEMPENHO NESTE APARELHO</h3><p data-performance>Meça 20 segundos de jogo para escolher a qualidade visual. O relatório fica neste aparelho.</p><button data-benchmark>MEDIR POR 20 SEGUNDOS</button><button data-report hidden>BAIXAR RELATÓRIO</button><p><a href="privacy.html" target="_blank" rel="noopener">Privacidade e dados locais ↗</a></p><div class="settings-footer"><button data-reset>RESTAURAR PADRÕES</button><button data-close>VOLTAR AO JOGO</button></div>`;for(const input of modal.querySelectorAll('[data-setting]')){const k=input.dataset.setting;if(input.type==='checkbox')input.checked=preferences[k];else input.value=preferences[k];input.onchange=()=>updatePreferences({[k]:input.type==='checkbox'?input.checked:k==='touchScale'?+input.value:input.value})}modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-reset]').onclick=()=>{updatePreferences({difficulty:'standard',motion:'system',contrast:false,largeText:false,quality:'auto',touchScale:1,showHints:true,bindings:{}});paint()};modal.querySelector('[data-benchmark]').onclick=()=>{modal.close();startBenchmark()};modal.querySelector('[data-report]').onclick=downloadBenchmark;for(const b of modal.querySelectorAll('[data-bind]'))b.onclick=()=>{binding=b.dataset.bind;b.textContent='Pressione a tecla…';modal.querySelector('#binding-status').textContent='Escolhendo tecla para '+labels[binding]};}
launch.onclick=()=>{window.dispatchEvent(new Event('brasa:modal'));paint();modal.showModal()};modal.addEventListener('close',()=>{binding=null;launch.focus()});
modal.addEventListener('keydown',e=>{e.stopPropagation();if(!binding)return;e.preventDefault();if(e.code==='Escape'){binding=null;paint();return}const used=Object.entries({...Object.fromEntries(canonicalKeys.map(k=>[k,k])),...preferences.bindings});const bindings={...preferences.bindings};const previous=bindings[binding]||binding;for(const [command,key]of used)if(command!==binding&&key===e.code)bindings[command]=previous;bindings[binding]=e.code;updatePreferences({bindings});binding=null;paint()});
export function announce(text){let live=document.getElementById('brasa-live');if(!live){live=document.createElement('p');live.id='brasa-live';live.className='sr-live';live.setAttribute('role','status');live.setAttribute('aria-live','polite');document.body.append(live)}live.textContent=text}

window.addEventListener('brasa:benchmark-result',e=>{paint();modal.querySelector('[data-performance]').textContent=e.detail.averageFps+' FPS médios · 95% dos quadros abaixo de '+e.detail.p95FrameMs+' ms. Resultado deste navegador; teste também em aparelho físico.';modal.querySelector('[data-report]').hidden=false;window.dispatchEvent(new Event('brasa:modal'));if(!modal.open)modal.showModal()});
